import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.DncwoWA8.js";const o="/projects/ai-skills/diagrams/build-test-first.svg",f=JSON.parse('{"title":"Build one behavior slice test-first","description":"","frontmatter":{"title":"Build one behavior slice test-first"},"headers":[],"relativePath":"workflows/build-test-first.md","filePath":"workflows/build-test-first.md"}'),r={name:"workflows/build-test-first.md"};function l(n,e,d,h,c,p){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="build-one-behavior-slice-test-first" tabindex="-1">Build one behavior slice test-first <a class="header-anchor" href="#build-one-behavior-slice-test-first" aria-label="Permalink to &quot;Build one behavior slice test-first&quot;">​</a></h1><p>This is a focused procedure. For its place in a larger workflow, see <a href="/projects/ai-skills/workflows/implement-a-task.html">Implement a planned task</a>.</p><p>The owner explicitly wants test-first development and the behavior is agreed.</p><p><strong>Finish with:</strong> An observed red test and the smallest green implementation at a user-confirmed seam.</p><h2 id="read-the-diagram" tabindex="-1">Read the diagram <a class="header-anchor" href="#read-the-diagram" aria-label="Permalink to &quot;Read the diagram&quot;">​</a></h2><p><img src="'+o+'" alt="Build one behavior slice test-first: suggested skill handoffs with approval stops where applicable."></p><p><a href="/projects/ai-skills/diagrams/build-test-first.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/build-test-first.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/build-test-first.json">Editable candidate</a></p><p>Arrows show this suggested sequence, not declared <code>requires</code> dependencies. Approval arrows are conditional. Declining a gate stops that branch without authorizing its writes. The numbered steps below are the text equivalent of the diagram.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use a trusted project and follow its instructions. Confirm the requested scope, installed skills, runtime tools, and any required workspace or approval. This selection includes the catalogued instruction requirements <a href="/projects/ai-skills/skills/coding.html"><code>coding</code></a>. Resolve them before use.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Use approved isolation.</strong> <a href="/projects/ai-skills/skills/isolated-workspace.html"><code>isolated-workspace</code></a> provides the guidance for this step.</li><li><strong>Resolve language guidance.</strong> <a href="/projects/ai-skills/skills/coding-with-rules.html"><code>coding-with-rules</code></a> provides the guidance for this step.</li><li><strong>Run one failing behavior test.</strong> <a href="/projects/ai-skills/skills/tdd.html"><code>tdd</code></a> provides the guidance for this step.</li><li><strong>Make the slice pass.</strong> <a href="/projects/ai-skills/skills/tdd.html"><code>tdd</code></a> provides the guidance for this step.</li></ol><h2 id="where-to-stop" tabindex="-1">Where to stop <a class="header-anchor" href="#where-to-stop" aria-label="Permalink to &quot;Where to stop&quot;">​</a></h2><p>Confirm the test seams with the user before writing a test. Stop the red-to-green implementation loop at green; refactoring belongs to a separate authorized review-stage handoff, not this loop. Never claim an unobserved failure.</p><h2 id="optional-branches" tabindex="-1">Optional branches <a class="header-anchor" href="#optional-branches" aria-label="Permalink to &quot;Optional branches&quot;">​</a></h2><ul><li>Choose <a href="/projects/ai-skills/skills/document-project.html"><code>document-project</code></a> when implementation changes how readers use the project, or existing documentation blocks a real developer task.</li><li>Choose <a href="/projects/ai-skills/skills/code-review.html"><code>code-review</code></a> when you want changes since a fixed commit, branch, tag, or merge-base checked against both standards and the originating specification.</li></ul><p>Optional branches are not prerequisites or permission to launch another phase. You can omit them or stop at the stated result. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a> for the distinction.</p>',17)])])}const m=t(r,[["render",l]]);export{f as __pageData,m as default};
